import { Component, ChangeDetectionStrategy, signal, computed, inject } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';

@Component({
  selector: 'app-order-list',
  standalone: true,
  // Without OnPush this component is checked on every event anywhere in the
  // application, which is what makes a long list stutter while scrolling.
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (loading()) {
      <app-spinner />
    } @else {
      <ul>
        @for (order of visible(); track order.id) {
          <li>{{ order.reference }} — {{ order.totalMinor / 100 | currency }}</li>
        } @empty {
          <li>No orders match this filter.</li>
        }
      </ul>
    }
  `,
})
export class OrderListComponent {
  private readonly orders = inject(OrdersService);

  readonly all = signal<Order[]>([]);
  readonly filter = signal<OrderStatus | 'all'>('all');
  readonly loading = signal(true);

  // Recomputed only when one of its signals changes - not on every tick.
  readonly visible = computed(() => {
    const f = this.filter();
    return f === 'all' ? this.all() : this.all().filter((o) => o.status === f);
  });

  constructor() {
    this.orders.stream()
      // Unsubscribes when the component is destroyed. Without it, navigating
      // away and back subscribes again, and the handlers accumulate.
      .pipe(takeUntilDestroyed())
      .subscribe((orders) => {
        this.all.set(orders);
        this.loading.set(false);
      });
  }
}
